-- S28-01 — RLS de purchase_invoices y purchase_receipt_lines: solo dueño/admin de la empresa leen;
-- nadie escribe directo (la escritura va por RPC). Ver specs/S28-01-recepcion-con-factura.md.
begin;
create extension if not exists pgtap with schema extensions;
select plan(6);


set local role authenticated;
set local "request.jwt.claims" to '{"sub": "00000000-0000-0000-0000-000000028111", "role": "authenticated"}';

select is((select count(*)::int from public.purchase_invoices), 1, 'A ve solo sus facturas');
select is((select count(*)::int from public.purchase_receipt_lines), 1, 'A ve solo sus líneas');
select is((select count(*)::int from public.purchase_invoices where tenant_id = '10000000-0000-0000-0000-000000028112'),
  0, 'A no ve facturas de B');
select throws_ok(
  $$insert into public.purchase_invoices (tenant_id, purchase_id, supplier_id, number, issued_on, subtotal, tax, total, warehouse_id)
    values ('10000000-0000-0000-0000-000000028111', '50000000-0000-0000-0000-000000028111', '20000000-0000-0000-0000-000000028111',
            'F9', current_date, 1, 0, 1, '40000000-0000-0000-0000-000000028111')$$,
  '42501', null, 'Nadie escribe facturas directo (solo por RPC)');
select throws_ok($$update public.purchase_receipt_lines set qty = 99$$, '42501', null, 'Nadie edita líneas directo');
update public.purchases set invoiced_total = 0 where id = '50000000-0000-0000-0000-000000028111';
select ok((select invoiced_total from public.purchases where id = '50000000-0000-0000-0000-000000028111') is null,
  'Ni la deuda de la orden');

select * from finish();
rollback;
